#include "elit21/shopify/webhooks/FulfillmentWebhookHandler.h"
namespace elit21::shopify::webhooks {FulfillmentWebhookHandler::FulfillmentWebhookHandler():platform::BusinessComponent("FulfillmentWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}FulfillmentWebhookHandler::FulfillmentWebhookHandler(Database&database):FulfillmentWebhookHandler(){database_=&database;}Result<void>FulfillmentWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("FulfillmentWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::fulfillments_create,ShopifyWebhookTopic::fulfillments_update});}platform::OperationResult FulfillmentWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="FulfillmentWebhookHandler";return r;}}
